// LocalLog holds log entries for a key on this node
type LocalLog struct {
	Key   string `json:"key"`
	Val   int    `json:"val"`
	Offset int64 `json:"offset"`
}

// PerKeyState tracks the state of each key across nodes (via lin-kv)
type PerKeyState struct {
	Entries map[string]*LocalLog `json:"entries"`
}

// GlobalPerKeyState maintains aggregated state across all nodes
type GlobalPerKeyState struct {
	Key   string `json:"key"`
	Val   int    `json:"val"`
	Offset int64 `json:"offset"`
	Sender string `json:"sender"`
}

var (
	stdlog = os.Stderr
	nodes  = map[string]*Node{}
)

type Node struct {
	id          string
	linKV       maebast.KVStore
	pingID      string
	localLogs   map[string]*LocalLog
	keyStates   PerKeyState
	wg          sync.WaitGroup
	cancelFunc  context.CancelFunc
	ctx         context.Context
}

// Global state for the cluster (stored via lin-kv)
type ClusterState struct {
	Entries map[string]PerKeyEntry `json:"entries"`
}

// PerKeyEntry holds all entries for a key across nodes
type PerKeyEntry struct {
	Key   string        `json:"key"`
	Val   int           `json:"val"`
	Offset int64        `json:"offset"`
	Sender string       `json:"sender"`
}

func init() {
	go maebast.NewLinKV("maelstrom", "node", &nodes)
}

func newNode(ctx context.Context, id string) *Node {
	ctx = context.Background()
	node := &Node{
		id:          id,
		localLogs:   make(map[string]*LocalLog),
		keyStates:   PerKeyState{},
		ctx:         ctx,
	}

	// Initialize lin-kv with empty state
	lkv := maebast.NewLinKV(ctx)

	return node
}

func main() {
	m, err := maebast.NewNode()
	if err != nil {
		fmt.Fprintf(stdlog, "Failed to create node: %v\n", err)
		os.Exit(1)
	}

	h := m.Handle("init", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.InitMessage)
		if err != nil {
			return nil, true, err
		}
		node := newNode(m.ctx(), m.ID())
		m.Send(node, fmt.Sprintf("%v", node.id))

		return "ok", true, nil
	})

	h = m.Handle("send", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.SendMessage)
		if err != nil {
			return nil, true, err
		}
		return node.handleSend(ctx, msg)
	})

	h = m.Handle("poll", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.PollMessage)
		if err != nil {
			return nil, true, err
		}
		return node.handlePoll(ctx, msg)
	})

	h = m.Handle("commit_offsets", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.CommitOffsetsMessage)
		if err != nil {
			return nil, true, err
		}
		return node.handleCommitOffsets(ctx, msg)
	})

	h = m.Handle("list_committed_offsets", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.ListCommittedOffsetsMessage)
		if err != nil {
			return nil, true, err
		}
		return node.handleListCommittedOffsets(ctx, msg)
	})

	m.Run()
}

