package main

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/jepsen-io/maelstrom/demo/go"
)

// Node represents a cluster node
type Node struct {
	id          string
	nodeIDs     []string
	localLogs   map[string][]LocalEntry  // key -> list of entries, sorted by offset
	keyState    map[string]*KeyState      // global state tracked via lin-kv (simplified: local)
	nextSeq     int64                     // sequence number for offsets
	sent        map[int]map[string]string // sent replies per message ID per node type
	recv        map[int]msgReceived       // received messages per message ID
}

type LocalEntry struct {
	Key   string `json:"key"`
	Value int    `json:"val"`
	Offset int64 `json:"offset"`
}

// KeyState tracks the state of entries across all nodes for a key
type KeyState struct {
	Key   string   `json:"key"`
	Value int      `json:"val"`
	Offset int64   `json:"offset"`
	Sender string  `json:"sender"`
}

type msgReceived struct {
	id    string
	body  interface{}
	src   string
	typ   string
}

var nodes = map[string]*Node{}

func main() {
	m, err := maebast.NewNode()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to create node: %v\n", err)
		os.Exit(1)
	}

	h := m.Handle("init", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.InitMessage)
		nodeID := msg.ID()
		nodeIDs := msg.NodeIDs()
		initNode(nodeID, nodeIDs)

		return "ok", true, nil
	})

	h = m.Handle("send", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.SendMessage)
		return handleSend(ctx, msg)
	})

	h = m.Handle("poll", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.PollMessage)
		return handlePoll(ctx, msg)
	})

	h = m.Handle("commit_offsets", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.CommitOffsetsMessage)
		return handleCommitOffsets(ctx, msg)
	})

	h = m.Handle("list_committed_offsets", func(ctx context.Context, src string, body interface{}) (reply interface{}, done bool, err error) {
		msg := body.(mae.ListCommittedOffsetsMessage)
		return handleListCommittedOffsets(ctx, msg)
	})

	m.Run()
}

func initNode(id string, nodeIDs []string) {
	nodes[id] = &Node{
		id:       id,
		nodeIDs:  nodeIDs,
		localLogs: make(map[string][]LocalEntry),
		keyState: make(map[string]*KeyState),
		sent:     make(map[int]map[string]string),
		recv:     make(map[int]msgReceived),
	}

	for i := range nodeIDs {
		nodeID := nodeIDs[i]
		if nodes[nodeID] != nil {
			syncNode(id, nodeIDs)
			return
		}
	}
}

// Sync state between nodes
func syncNode(fromID, toID string) {
	var n *Node
	for _, nid := range nodes[fromID].nodeIDs {
		if nid == fromID {
			n = nodes[fromID]
		} else {
			n = nodes[nid]
		}
		break
	}

	if n != nil {
		syncEntries(nodes[toID], n)
		return
	}
}

// syncEntries syncs entries from another node to this one
func syncEntries(to, from *Node) {
	for key, state := range from.keyState {
		to.keyState[key] = &KeyState{
			Key:   key,
			Value: state.Value,
			Offset: state.Offset,
			Sender: state.Sender,
		}
	}

	for key := range to.localLogs {
		for _, entry := range from.localLogs[key] {
			to.localLogs[key] = append(to.localLogs[key], entry)
		}
	}
}

func handleSend(ctx context.Context, msg mae.SendMessage) (reply interface{}, done bool, err error) {
	key := msg.Key()
	value := int(msg.Message())
	msgID := msg.ID().(int)

	localNode := nodes[msg.NodeID()]
	if localNode == nil {
		return nil, false, fmt.Errorf("node not found")
	}

	offset := localNode.nextSeq + 1
	entry := LocalEntry{
		Key:   key,
		Value: value,
		Offset: offset,
	}

	localNode.localLogs[key] = append(localNode.localLogs[key], entry)
	localNode.nextSeq += 2

	sendOKBody := mae.SendOkBody{
		InReplyTo: int(msgID),
		Offset:    offset,
	}

	replyBody := mae.Reply{
		MsgID:  msgID,
		Typ:    "send_ok",
		Sender: msg.NodeID(),
		Val: sendOKBody,
	}

	localNode.send[msgID]["ok"] = fmt.Sprintf("%v", replyBody)

	return replyBody, true, nil
}

func handlePoll(ctx context.Context, msg mae.PollMessage) (reply interface{}, done bool, err error) {
	offsets := msg.Offsets()
	pollOK := mae.PollOkBody{}

	// Sort entries by offset
	sortedLogs := make([]map[string][]LocalEntry, len(offsets))
	for i, key := range offsets.Keys() {
		localNode := nodes[msg.NodeID()]
		if localNode == nil {
			return nil, false, fmt.Errorf("node not found")
		}

		entries := localNode.localLogs[key]
		if len(entries) == 0 {
			offsets.Keys()[i] = key
			sortedLogs[i] = []LocalEntry{}
		} else {
			var sorted []LocalEntry
			for _, entry := range entries {
				if entry.Offset >= offsets.Offsets()[key] {
					sorted = append(sorted, entry)
				}
			}
			offsets.Keys()[i] = key
			sortedLogs[i] = sorted
		}
	}

	pollOK.Messages = make(map[string][]Pair)
	for i, entries := range sortedLogs {
		key := offsets.Keys()[i]
		if len(entries) > 0 {
			startOffset := offsets.Offsets()[key]
			var pairs []Pair
			for _, entry := range entries {
				pairs = append(pairs, Pair{Offset: entry.Offset, Val: entry.Value})
				if entry.Offset == startOffset {
					break
				}
			}
			pollOK.Messages[key] = pairs
		}
	}

	replyBody := mae.Reply{
		MsgID:  msg.ID().(int),
		Typ:    "poll_ok",
		Sender: msg.NodeID(),
		Poll:   pollOK,
	}

	return replyBody, true, nil
}

func handleCommitOffsets(ctx context.Context, msg mae.CommitOffsetsMessage) (reply interface{}, done bool, err error) {
	offsets := msg.Offsets()
	commitOffsetsOk := mae.CommitOffsetsOkBody{}
	committed := make(map[string]int64)

	for key, offset := range offsets.Offsets() {
		localNode := nodes[msg.NodeID()]
		if localNode == nil {
			return nil, false, fmt.Errorf("node not found")
		}

		logEntries := localNode.localLogs[key]
		var lastOffset int64 = -1
		for _, entry := range logEntries {
			if entry.Offset >= offset && (lastOffset < 0 || entry.Offset > lastOffset) {
				lastOffset = entry.Offset
			}
		}

		committed[strconv.FormatInt(offset, 10)] = lastOffset
	}

	replyBody := mae.Reply{
		MsgID:  msg.ID().(int),
		Typ:    "commit_offsets_ok",
		Sender: msg.NodeID(),
		Val: commitOffsetsOk,
	}

	return replyBody, true, nil
}

func handleListCommittedOffsets(ctx context.Context, msg mae.ListCommittedOffsetsMessage) (reply interface{}, done bool, err error) {
	keys := msg.Keys()
	listCommittedOffsetOK := mae.ListCommittedOffsetOKBody{}
	committed := make(map[string]int64)

	for _, key := range keys.Keys() {
		localNode := nodes[msg.NodeID()]
		if localNode == nil {
			return nil, false, fmt.Errorf("node not found")
		}

		logEntries := localNode.localLogs[key]
		var lastOffset int64 = -1
		for _, entry := range logEntries {
			if entry.Offset > lastOffset {
				lastOffset = entry.Offset
			}
		}

		committed[strconv.FormatInt(lastOffset, 10)] = lastOffset
	}

	replyBody := mae.Reply{
		MsgID:  msg.ID().(int),
		Typ:    "list_committed_offsets_ok",
		Sender: msg.NodeID(),
		Val: listCommittedOffsetOK,
	}

	return replyBody, true, nil
}

